function TopBar({ onMenuClick, navigationOpen, isDesktop }) {
  const { user, signOut } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  const [anchor, setAnchor] = useState(null);
  const pageTitle = pageTitles.find(({ match }) => match.test(location.pathname))?.title || "EFAR Payroll";
  const displayName = user?.fullName || user?.name || "EFAR User";
  const displayRole = user?.role || "User";
  const initials = displayName.split(/\s+/).filter(Boolean).map((part) => part[0]).slice(0, 2).join("").toUpperCase() || "EU";

  const handleLogout = async () => {
    setAnchor(null);
    await signOut();
    navigate("/login", { replace: true });
  };

  return (
    <AppBar position="fixed" color="inherit" elevation={0} className="app-topbar">
      <Toolbar>
        <IconButton
          className="topbar-menu-button"
          edge="start"
          onClick={onMenuClick}
          aria-label={navigationOpen ? "Close navigation" : "Open navigation"}
          aria-expanded={navigationOpen}
          aria-controls={isDesktop ? "desktop-navigation" : "mobile-navigation"}
        >
          <MenuRounded />
        </IconButton>
        <Typography className="topbar-page-title" component="h1">{pageTitle}</Typography>
        <Box className="topbar-account">
          <IconButton
            onClick={(event) => setAnchor(event.currentTarget)}
            aria-label="Open account menu"
            aria-haspopup="menu"
            aria-expanded={Boolean(anchor)}
          >
            <Avatar className="topbar-avatar">{initials}</Avatar>
          </IconButton>
          <Box className="topbar-user-copy">
            <Typography variant="body2" fontWeight={700}>{displayName}</Typography>
            <Typography variant="caption" color="text.secondary" sx={{ textTransform: "capitalize" }}>{displayRole}</Typography>
          </Box>
          <IconButton className="topbar-account-arrow" size="small" onClick={(event) => setAnchor(event.currentTarget)} aria-label="Open account menu">
            <ExpandMoreRounded fontSize="small" />
          </IconButton>
        </Box>
        <Menu anchorEl={anchor} open={Boolean(anchor)} onClose={() => setAnchor(null)}>
          <MenuItem disabled><PersonRounded fontSize="small" sx={{ mr: 1 }} />{user?.email || displayName}</MenuItem>
          <Divider />
          <MenuItem onClick={handleLogout}><LogoutRounded fontSize="small" sx={{ mr: 1 }} />Log out</MenuItem>
        </Menu>
      </Toolbar>
    </AppBar>
  );
}

export default function AppLayout() {
  const theme = useTheme();
  const isDesktop = useMediaQuery(theme.breakpoints.up("md"));
  const [desktopCollapsed, setDesktopCollapsed] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);

  useEffect(() => {
    if (isDesktop) setMobileOpen(false);
  }, [isDesktop]);

  const handleMenuClick = () => {
    if (isDesktop) {
      setDesktopCollapsed((collapsed) => !collapsed);
    } else {
      setMobileOpen((open) => !open);
    }
  };

  const navigationOpen = isDesktop ? !desktopCollapsed : mobileOpen;

  return (
    <Box className={`application-shell${isDesktop && desktopCollapsed ? " sidebar-collapsed" : ""}`}>
      <TopBar onMenuClick={handleMenuClick} navigationOpen={navigationOpen} isDesktop={isDesktop} />
      <Box component="nav" aria-label="Application navigation">
        {isDesktop ? (
          !desktopCollapsed && (
            <Drawer
              id="desktop-navigation"
              variant="permanent"
              open
              sx={{ "& .MuiDrawer-paper": { width: drawerWidth } }}
            >
              <Sidebar />
            </Drawer>
          )
        ) : (
          <Drawer
            id="mobile-navigation"
            variant="temporary"
            open={mobileOpen}
            onClose={() => setMobileOpen(false)}
            ModalProps={{ keepMounted: false }}
            sx={{ "& .MuiDrawer-paper": { width: drawerWidth } }}
          >
            <Sidebar onNavigate={() => setMobileOpen(false)} />
          </Drawer>
        )}
      </Box>
      <Box component="main" className="application-main"><Outlet /></Box>
    </Box>
  );
}
import { useEffect, useState } from "react";
import { fetchPayPeriods } from "../api/payPeriods";
import "../styles/rosterSync.css";

function PayPeriodsPage() {
  const [periods, setPeriods] = useState([]);
  const [loading, setLoading] = useState(true);
  const [errorMessage, setErrorMessage] = useState("");
  const [showAllPeriods, setShowAllPeriods] = useState(false);
  const today = new Date();
  const windowStart = new Date(today);
  const windowEnd = new Date(today);
  windowStart.setMonth(windowStart.getMonth() - 3);
  windowEnd.setMonth(windowEnd.getMonth() + 3);
  const visiblePeriods = showAllPeriods ? periods : periods.filter((period) => {
    const startDate = new Date(`${period.startDate}T00:00:00`);
    const endDate = new Date(`${period.endDate}T23:59:59`);
    return endDate >= windowStart && startDate <= windowEnd;
  });

  useEffect(() => {
    fetchPayPeriods()
      .then((data) => setPeriods(data))
      .catch((error) => setErrorMessage(error.message))
      .finally(() => setLoading(false));
  }, []);

  return (
    <main className="roster-page">
      <header className="roster-intro"><h1>Pay Periods</h1><p>View the automatically generated payroll periods.</p></header>
      {errorMessage && <p className="roster-banner roster-error">{errorMessage}</p>}
      <section className="roster-card">
        <h2>Pay Periods</h2>
        <label className="roster-controls"><input type="checkbox" checked={showAllPeriods} onChange={(event) => setShowAllPeriods(event.target.checked)} />Show all periods</label>
        {loading && <p className="roster-empty">Loading pay periods...</p>}
        {!loading && visiblePeriods.length === 0 && <p className="roster-empty">No pay periods found.</p>}
        {!loading && visiblePeriods.length > 0 && <div className="roster-table-scroll"><table><thead><tr><th>Start date</th><th>End date</th><th>Status</th></tr></thead><tbody>{visiblePeriods.map((period) => <tr key={period.id} style={period.isActive ? { background: "#dcfce7", fontWeight: 700 } : undefined}><td>{period.startDate}</td><td>{period.endDate}</td><td>{period.isActive ? "Active" : "Inactive"}</td></tr>)}</tbody></table></div>}
      </section>
    </main>
  );
}

export default PayPeriodsPage;

